<script setup>import { ref, computed } from 'vue'; import { Play, Clock, LockKeyhole, Search } from 'lucide-vue-next'; import { games } from '../../data/content'; const query=ref(''); const filtered=computed(()=>games.filter(g=>(g.title+g.category).toLowerCase().includes(query.value.toLowerCase())))</script>
<template><div><section class="page-hero games-hero"><div class="shell"><span class="eyebrow">Edyn Game Hub</span><h1>Little games.<br><em>Big learning moments.</em></h1><p>Choose a skill and jump into quick, positive practice designed for little hands and growing minds.</p><RouterLink class="button button-sun" to="/play/tunde/games"><Play fill="currentColor" :size="17"/> Enter child mode</RouterLink></div></section><section class="section shell"><div class="catalog-tools"><label><Search/><input v-model="query" placeholder="Search games or skills"></label><div class="filter-pills"><button class="active">All games</button><button>Alphabet</button><button>Numbers</button><button>Shapes</button></div></div><div class="games-grid"><article v-for="(game,index) in filtered" :key="game.slug" class="game-card" :class="game.color"><div class="game-icon">{{game.icon}}</div><div class="game-meta"><span>{{game.category}}</span><span><Clock :size="14"/> {{game.minutes}} min</span></div><h3>{{game.title}}</h3><p>{{game.instruction}}</p><RouterLink v-if="index<3" class="play-button" :to="`/play/tunde/activity/${game.slug}`"><Play fill="currentColor"/> Play now</RouterLink><button v-else class="play-button locked"><LockKeyhole/> Family access</button></article></div></section></div></template>
